using System.ComponentModel.DataAnnotations;
namespace StockPilot.Core;
public sealed record Page<T>(IReadOnlyList<T> Items, int Total, int Number, int Size);
public sealed record ProductInput([Required, StringLength(64)] string Sku, [Required, StringLength(160)] string Name, Guid CategoryId, Guid UnitId, decimal SellingPrice, decimal MinimumStock, [StringLength(1000)] string? Description = null, [StringLength(64)] string? Barcode = null);
public sealed record ProductDto(Guid Id, string Sku, string Name, Guid CategoryId, Guid UnitId, decimal SellingPrice, decimal? AverageCost, decimal Stock, decimal MinimumStock, bool Active, string Description, string? Barcode);
public sealed record PartnerInput([Required, StringLength(160)] string Name, [StringLength(160)] string? Contact = null, [StringLength(500)] string? Address = null, [StringLength(1000)] string? Notes = null);
public sealed record ItemInput(Guid ProductId, decimal Quantity, decimal UnitCost = 0);
public sealed record DraftInput(DocumentKind Kind, Guid? PartnerId, [Required] List<ItemInput> Items, decimal Discount = 0, decimal TaxRate = 0, [StringLength(120)] string? Reference = null, Guid Key = default);
public sealed record KeyInput(Guid Key);
public sealed record AdjustmentInput(Guid ProductId, decimal Change, [Required, StringLength(300)] string Reason, decimal UnitCost, Guid Key);
public sealed record PaymentInput(decimal Amount, PaymentMethod Method, Guid Key, [StringLength(300)] string? Reason = null);
public sealed record ReverseInput([Required, StringLength(300)] string Reason, Guid Key);
public sealed record DocumentLineDto(Guid ProductId, string ProductName, string Sku, decimal Quantity, decimal UnitPrice, decimal? UnitCost, decimal LineTotal);
public sealed record PaymentDto(Guid Id, decimal Amount, bool Refund, PaymentMethod Method, string Reason, DateTime CreatedUtc);
public sealed record DocumentDto(Guid Id, DocumentKind Kind, DocumentState State, string Number, Guid? PartnerId, string PartnerName, string Reference, string ActorId, DateTime CreatedUtc, DateTime? CompletedUtc, decimal Subtotal, decimal Discount, decimal TaxRate, decimal Tax, decimal Total, decimal Paid, decimal Refunded, decimal Outstanding, string PaymentState, IReadOnlyList<DocumentLineDto> Items, IReadOnlyList<PaymentDto> Payments);
public sealed record LookupDto(Guid Id, string Name);
public sealed record PartnerDto(Guid Id, string Kind, string Name, string Contact, string Address, string Notes, bool Active);
public sealed record DocumentSummary(Guid Id, string Number, DocumentKind Kind, DocumentState State, string PartnerName, DateTime CreatedUtc, decimal Total);
public sealed record GroupTotal(string Label, decimal Amount, decimal Quantity);
public sealed record ReportDto(DateTime From, DateTime To, decimal SalesSubtotal, decimal Discounts, decimal SalesTax, decimal Revenue, decimal Refunds, decimal NetRevenue, decimal Cogs, decimal GrossProfitEstimate, decimal PurchaseTotal, decimal InventoryValue, decimal Outstanding, int LowStock, int OutOfStock, IReadOnlyList<GroupTotal> Daily, IReadOnlyList<GroupTotal> Products, IReadOnlyList<GroupTotal> Categories, IReadOnlyList<GroupTotal> Methods, IReadOnlyList<GroupTotal> Staff);
